"use strict";(self.webpackChunkdocumentation=self.webpackChunkdocumentation||[]).push([[9997],{30070:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>o,default:()=>d,frontMatter:()=>i,metadata:()=>r,toc:()=>h});var a=n(86070),s=n(25710);const i={sidebar_position:4,title:"Conformity Vocabulary Catalogue"},o="Conformity Vocabulary Catalogue",r={id:"reference-implementation/data-models/conformity-vocabulary-catalogue",title:"Conformity Vocabulary Catalogue",description:"A conformity claim in a credential records what was assessed and what the assessment found, but it does not carry the definitions it is assessing against. Instead it points at them: a conformity scheme published by whoever owns it, usually a versioned profile within that scheme, and the criteria the assessment covered. Those pointers are URIs, and a claim may name fewer of them than you expect, since a profile is not required.",source:"@site/versioned_docs/version-0.4.0/reference-implementation/data-models/conformity-vocabulary-catalogue.md",sourceDirName:"reference-implementation/data-models",slug:"/reference-implementation/data-models/conformity-vocabulary-catalogue",permalink:"/tests-untp/docs/reference-implementation/data-models/conformity-vocabulary-catalogue",draft:!1,unlisted:!1,editUrl:"https://github.com/uncefact/tests-untp/tree/next/documentation/versioned_docs/version-0.4.0/reference-implementation/data-models/conformity-vocabulary-catalogue.md",tags:[],version:"0.4.0",sidebarPosition:4,frontMatter:{sidebar_position:4,title:"Conformity Vocabulary Catalogue"},sidebar:"tutorialSidebar",previous:{title:"Conformity Handling",permalink:"/tests-untp/docs/reference-implementation/data-models/conformity-handling"},next:{title:"Adding a Bridge",permalink:"/tests-untp/docs/reference-implementation/data-models/adding-a-bridge"}},c={},h=[{value:"The UNTP v0.7 model",id:"the-untp-v07-model",level:2},{value:"Where schemes come from",id:"where-schemes-come-from",level:2},{value:"Operator seeding, live",id:"operator-seeding-live",level:3},{value:"Discovery from the UNTP register, not operational",id:"discovery-from-the-untp-register-not-operational",level:3},{value:"Tenant-level import, not built",id:"tenant-level-import-not-built",level:3},{value:"Keeping the catalogue current",id:"keeping-the-catalogue-current",level:2},{value:"What each tenant sees",id:"what-each-tenant-sees",level:2},{value:"Using the catalogue",id:"using-the-catalogue",level:2}];function l(e){const t={a:"a",code:"code",h1:"h1",h2:"h2",h3:"h3",mermaid:"mermaid",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.h1,{id:"conformity-vocabulary-catalogue",children:"Conformity Vocabulary Catalogue"}),"\n",(0,a.jsxs)(t.p,{children:["A conformity claim in a credential records what was assessed and what the assessment found, but it does not carry the definitions it is assessing against. Instead it points at them: a ",(0,a.jsx)(t.strong,{children:"conformity scheme"})," published by whoever owns it, usually a versioned ",(0,a.jsx)(t.strong,{children:"profile"})," within that scheme, and the ",(0,a.jsx)(t.strong,{children:"criteria"})," the assessment covered. Those pointers are URIs, and a claim may name fewer of them than you expect, since a profile is not required."]}),"\n",(0,a.jsx)(t.p,{children:"For those URIs to mean anything to the Reference Implementation, it needs the scheme documents they refer to. This page describes where those documents come from, how they are kept current, and which tenant sees which of them."}),"\n",(0,a.jsx)(t.h2,{id:"the-untp-v07-model",children:"The UNTP v0.7 model"}),"\n",(0,a.jsxs)(t.p,{children:["Under ",(0,a.jsx)(t.a,{href:"https://untp.unece.org/docs/specification/ConformityVocabularyCatalog",children:"UNTP v0.7"}),", UNECE does not publish the schemes themselves. The catalogue is to be a ",(0,a.jsx)(t.strong,{children:"register of pointer URIs"}),': a list saying "a conformity scheme lives over there". Each scheme owner publishes their own scheme document at their own stable URI, and that document inlines its profiles, and each profile inlines its criteria.']}),"\n",(0,a.jsxs)(t.p,{children:["Two consequences shape everything below. Scheme content is owned and changed by other people, so a copy held here can go stale. And profile and criterion URIs are independently versioned while a scheme URI is not, so a claim naming ",(0,a.jsx)(t.code,{children:".../criterion/forced-labour/1.0.0"})," is naming one exact revision of that criterion."]}),"\n",(0,a.jsxs)(t.p,{children:["The Reference Implementation keeps its own ",(0,a.jsx)(t.strong,{children:"local catalogue"})," of scheme documents it has resolved. Every check it performs, and everything its API returns, is answered from that local catalogue rather than from the network."]}),"\n",(0,a.jsx)(t.h2,{id:"where-schemes-come-from",children:"Where schemes come from"}),"\n",(0,a.jsx)(t.p,{children:"A fresh deployment holds no schemes at all. The core seed does not insert any, so an issuer browsing the catalogue on an untouched install gets an empty list rather than a starter set. Schemes arrive only through one of the sources below."}),"\n",(0,a.jsx)(t.p,{children:"Three sources can feed the local catalogue. They are at different stages, and the difference matters if you are deciding what to rely on today."}),"\n",(0,a.jsx)(t.mermaid,{value:'flowchart LR\n    Manifest["Custom seed manifest<br/>(operator)"] --\x3e|live| Catalogue[("Local catalogue")]\n    Register["UNTP register<br/>(CVC_REGISTRY_URL)"] -.->|not operational| Catalogue\n    Tenant["Tenant import<br/>(per tenant)"] -.->|not built| Catalogue\n    Catalogue --\x3e API["CVC browse API"]\n    Catalogue --\x3e Validation["Conformity claim validation<br/>issuing a v0.7.0 DCC"]'}),"\n",(0,a.jsx)(t.h3,{id:"operator-seeding-live",children:"Operator seeding, live"}),"\n",(0,a.jsxs)(t.p,{children:["An operator lists scheme documents in the ",(0,a.jsx)(t.a,{href:"../operations/custom-seed",children:"custom seed manifest"}),", either as a URL to fetch or as a file mounted into the container. These land in the system tenant and are visible to every tenant."]}),"\n",(0,a.jsxs)(t.p,{children:["The manifest is the source of truth for the schemes it owns. An entry with no matching row is inserted, a changed entry is updated in place, and a scheme whose entry has been removed from the manifest is deleted along with its profiles. Only operator-seeded schemes are ever removed this way, and when a file entry cannot be resolved the removal pass is skipped entirely rather than deleting schemes on the strength of an incomplete manifest. ",(0,a.jsx)(t.a,{href:"../operations/custom-seed",children:"Custom seed"})," covers the manifest format and this behaviour in full."]}),"\n",(0,a.jsxs)(t.p,{children:["Seeded schemes also refresh their ",(0,a.jsx)(t.strong,{children:"content"})," from source, not just their membership. At boot every manifest entry is re-ingested; URL entries go through a conditional fetch and file entries are compared by digest, so an unchanged document is detected cheaply and skips parsing and persistence. Between boots, an interval re-fetches the URL-seeded schemes on the nominal cadence set by ",(0,a.jsx)(t.code,{children:"CVC_REFRESH_INTERVAL_HOURS"}),", spread by a small jitter so instances do not all wake together (see ",(0,a.jsx)(t.a,{href:"../operations/startup",children:"Startup"}),"). The periodic refresher handles URL-seeded schemes only; schemes seeded from a mounted file are re-read at boot instead."]}),"\n",(0,a.jsx)(t.h3,{id:"discovery-from-the-untp-register-not-operational",children:"Discovery from the UNTP register, not operational"}),"\n",(0,a.jsxs)(t.p,{children:["The intent is that the Reference Implementation reads the UNECE register named by ",(0,a.jsx)(t.code,{children:"CVC_REGISTRY_URL"}),", follows each pointer URI, and ingests the schemes it finds."]}),"\n",(0,a.jsxs)(t.p,{children:["This is not running. The resolution and ingest machinery exists, but nothing triggers it and no startup path reads that variable, so setting it has no effect today. UNTP's current published artefact is a scheme owners registration page rather than the machine-readable register this would read, which is promised before the first stable release. Wiring the trigger is tracked in ",(0,a.jsx)(t.a,{href:"https://github.com/uncefact/tests-untp/issues/690",children:"#690"}),", and the wider discovery capability in ",(0,a.jsx)(t.a,{href:"https://github.com/uncefact/tests-untp/issues/543",children:"#543"}),"."]}),"\n",(0,a.jsx)(t.h3,{id:"tenant-level-import-not-built",children:"Tenant-level import, not built"}),"\n",(0,a.jsx)(t.p,{children:"The intent is that a tenant supplies a scheme URI and gets that scheme resolved into its own lane, without an operator changing the deployment's manifest. This is useful when a scheme matters to one tenant and not to the platform."}),"\n",(0,a.jsx)(t.p,{children:"No endpoint exists for this yet, and nothing in the product writes a tenant-owned scheme row. The design is recorded in ADR-033."}),"\n",(0,a.jsx)(t.h2,{id:"keeping-the-catalogue-current",children:"Keeping the catalogue current"}),"\n",(0,a.jsx)(t.p,{children:"Because scheme owners can change a document after it is published, a copy here is only as good as its last successful fetch. A successful re-ingest replaces the stored scheme, its profiles, and its criteria with what the document now says. Within a tenant's lane a canonical URI appears once, so a changed document updates what is already there rather than accumulating copies of the same URI beside it."}),"\n",(0,a.jsx)(t.p,{children:"A failed fetch leaves the previous content in place rather than emptying the catalogue. That is the safe behaviour, but it means a stale entry and a current one look identical through the browse API, which returns only the catalogue content and no fetch metadata. An operator checking whether refresh is actually working should look at the startup and interval logs, where each pass records what it fetched and what failed."}),"\n",(0,a.jsxs)(t.p,{children:["What is implemented today is the seeded-scheme refresh described above. Refresh driven by register discovery waits on the discovery trigger, and an endpoint to force a refresh on demand rather than waiting for the interval is tracked in ",(0,a.jsx)(t.a,{href:"https://github.com/uncefact/tests-untp/issues/666",children:"#666"}),"."]}),"\n",(0,a.jsx)(t.h2,{id:"what-each-tenant-sees",children:"What each tenant sees"}),"\n",(0,a.jsx)(t.p,{children:"A tenant browsing the catalogue sees the system catalogue plus anything in its own lane. Where the same canonical URI exists in both, the system-tenant entry wins, so a tenant cannot shadow a platform-provisioned scheme with a private copy of the same URI. The same precedence applies when a credential is validated during issuance, so what a tenant browses and what its claims are checked against agree."}),"\n",(0,a.jsxs)(t.p,{children:["Since tenant import is not built, every tenant sees the same system catalogue today. How a tenant's own entry should behave once its URI is also registered upstream is tracked in ",(0,a.jsx)(t.a,{href:"https://github.com/uncefact/tests-untp/issues/664",children:"#664"}),"."]}),"\n",(0,a.jsx)(t.h2,{id:"using-the-catalogue",children:"Using the catalogue"}),"\n",(0,a.jsxs)(t.p,{children:["Issuers browse the catalogue through the ",(0,a.jsx)(t.a,{href:"../api/conformity-vocabulary-catalogue",children:"Conformity Vocabulary Catalogue API"}),", drilling from scheme to profile to criteria and taking the canonical URIs to put in a claim."]}),"\n",(0,a.jsxs)(t.p,{children:["Conformity claims in a ",(0,a.jsx)(t.strong,{children:"UNTP v0.7.0"})," Digital Conformity Credential are checked against the catalogue as it is issued. Earlier DCC versions are still supported for issuance and are seeded by default, but they carry no claim extraction, so a v0.6.0 or v0.6.1 credential is issued without this check and without CVC warnings."]}),"\n",(0,a.jsxs)(t.p,{children:["The check is advisory and never blocks a credential: see ",(0,a.jsx)(t.a,{href:"../api/credentials#cvc-compliance-conformity-credentials-only",children:"CVC compliance"})," on the Credentials API page for the warnings it produces, and ",(0,a.jsx)(t.a,{href:"./conformity-handling",children:"Conformity Handling"})," for how conformity data is modelled across the credential types that carry it."]})]})}function d(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},25710:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>r});var a=n(30758);const s={},i=a.createContext(s);function o(e){const t=a.useContext(i);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);